const TOTAL_MISSIONS=1045;
const gamePalettes=['#dfe9ff','#ffe0e9','#ffead0','#e8dfff','#daf2e7','#eee0ff','#d8edff','#ffe2d2','#ffdfdf','#e1f0cf','#fff0bf','#d6f1e2','#e7e0ff'];
function pathIds(type){const i=E.types.findIndex(t=>t.id===type);return i<0?[]:i<10?E.range(100).map(n=>Math.floor(n/20)*200+n%20*10+i):E.range(15).map(n=>1000+(i-10)*15+n);}
function nextInPath(type){const ids=pathIds(type);return ids.find(id=>!progress.done.includes(id))??ids[0];}
function unlocked(id){const x=E.make(id),ids=pathIds(x.type),i=ids.indexOf(id);return progress.done.includes(id)||i===0||ids.slice(0,i).every(n=>progress.done.includes(n));}
function journey(type){stop();filter=type;const t=E.types.find(t=>t.id===type);if(!t)return home();m=null;state=null;applyWorldTheme();const ids=pathIds(type),done=ids.filter(id=>progress.done.includes(id)).length,target=nextInPath(type);app.innerHTML=`<button class="back" data-action="home">← Pilih permainan</button><section class="path-hero"><span class="path-mascot" aria-hidden="true">${t.icon}</span><div><h1>${t.name}</h1><p>Selesaikan level untuk membuka yang berikutnya.</p><button class="primary" data-action="open" data-value="${target}">${done===ids.length?'↻ Main lagi':done?'▶ Lanjut bermain':'▶ Mulai level 1'}</button></div><div class="star-bank">⭐<b>${done} / ${ids.length}</b><small>Bintang terkumpul</small></div></section><div class="path-stages">${E.levels.map((l,stage)=>`<section class="path-stage"><h2>${l.icon} ${l.short}</h2><div class="level-path">${ids.filter(id=>E.make(id).level===stage).map(id=>{const x=E.make(id),i=ids.indexOf(id),finished=progress.done.includes(id),ready=unlocked(id);return `<button class="level-node ${finished?'completed':ready?'available':'locked'}" data-action="open" data-value="${id}" ${ready?'':'disabled'} aria-label="Level ${i+1}, ${E.themes[x.theme].name}, ${finished?'selesai':ready?'siap dimainkan':'terkunci'}"><span>${finished?'⭐':ready?E.themes[x.theme].icon:'🔒'}</span><b>Level ${i+1}</b><small>${E.themes[x.theme].name}</small></button>`;}).join('')}</div></section>`).join('')}</div>`;window.scrollTo(0,0);}
function syncShell(){const count=$('#starCount');if(count)count.textContent=progress.done.length;}
function gameMenu(){stop();applyWorldTheme();m=null;state=null;filter=null;syncShell();app.innerHTML=`<section class="simple-menu"><h1>Pilih permainanmu! 🚀</h1><p>Main, coba, kumpulkan bintang.</p><div class="arcade-grid">${E.types.map((t,i)=>{const ids=pathIds(t.id),done=ids.filter(id=>progress.done.includes(id)).length;return `<button class="arcade-card" style="--game-tint:${gamePalettes[i]};--float-delay:${i%4*-.7}s" data-action="journey" data-value="${t.id}"><span class="arcade-icon" aria-hidden="true">${t.icon}</span><h2>${t.name}</h2><span class="arcade-progress"><span>⭐ ${done} / ${ids.length}</span><b>▶</b></span></button>`;}).join('')}</div></section>`;window.scrollTo(0,0);}
